#include <cstdio>
#include <vector>

using namespace std;

const int MAXN = 300005;

int n, m;
int color[MAXN];
vector<int> graph[MAXN];

void danhdau(int x, int g) {
    color[x] = g;

    for (int p : graph[x]) {
        int count[2] = {0, 0};

        for (int v : graph[p]) {
            if (color[v] == 0 || color[v] == 1)
                ++count[color[v]];
        }

        if (color[p] == 0 && count[0] > 1) {
            for (int v : graph[p]) {
                if (color[v] == 0) {
                    danhdau(v, 1);
                    break;
                }
            }
        } else if (color[p] == 1 && count[1] > 1) {
            for (int v : graph[p]) {
                if (color[v] == 1) {
                    danhdau(v, 0);
                    break;
                }
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &m);

    for (int i = 0; i < m; ++i) {
        int x, y;
        scanf("%d%d", &x, &y);
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    for (int i = 1; i <= n; ++i)
        color[i] = 2;

    for (int i = 1; i <= n; ++i) {
        int count0 = 0;

        for (int v : graph[i]) {
            if (color[v] == 0)
                ++count0;
        }

        danhdau(i, count0 > 1 ? 1 : 0);
    }

    for (int i = 1; i <= n; ++i)
        printf("%d", color[i]);

    return 0;
}

