#include <cstdio>
#include <vector>
#include <utility>

using namespace std;

const int MAXN = 300005;

int n, m;
int color[MAXN];
vector<int> graph[MAXN];

void danhdau(int start, int startColor) {
    vector<pair<int, int>> stk;
    color[start] = startColor;
    stk.push_back({start, 0});

    while (!stk.empty()) {
        int x = stk.back().first;
        int &index = stk.back().second;

        if (index >= static_cast<int>(graph[x].size())) {
            stk.pop_back();
            continue;
        }

        int p = graph[x][index++];
        int count[2] = {0, 0};

        for (int neighbor : graph[p]) {
            if (color[neighbor] == 0 || color[neighbor] == 1) {
                ++count[color[neighbor]];
            }
        }

        int newColor = -1;
        if (color[p] == 0 && count[0] > 1) {
            newColor = 1;
        } else if (color[p] == 1 && count[1] > 1) {
            newColor = 0;
        }

        if (newColor != -1) {
            int oldColor = color[p];
            for (int neighbor : graph[p]) {
                if (color[neighbor] == oldColor) {
                    color[neighbor] = newColor;
                    stk.push_back({neighbor, 0});
                    break;
                }
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &m);

    for (int i = 0; i < m; ++i) {
        int x, y;
        scanf("%d%d", &x, &y);
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    for (int i = 1; i <= n; ++i) {
        color[i] = 2;
    }

    for (int i = 1; i <= n; ++i) {
        int count0 = 0;
        for (int neighbor : graph[i]) {
            if (color[neighbor] == 0) {
                ++count0;
            }
        }
        danhdau(i, count0 > 1 ? 1 : 0);
    }

    for (int i = 1; i <= n; ++i) {
        printf("%d", color[i]);
    }

    return 0;
}

